// 강적/사도/천상사강/신격 등은 "안 나왔으니 한번 등장" 식 스포트라이트 회전에 절대 넣지 않는다.
// 이미 활성화된 사건/훅/사용자 직접 탐색이 있을 때만 기존 canon 규칙으로 등장 가능하다.
const ROTATION_LOCKED = new Set([
  'arien','aris','asmo','beelzebub','bellian','carne','delpirem','etera',
  'fria','kartia','levian','lily_lumina','nemesis','seriel','sloth','veradin'
]);

function deptOfPc(pc = {}) {
  const d = String(pc?.department || '');
  if (/기사/.test(d)) return 'knight';
  if (/마법/.test(d)) return 'magic';
  if (/신학|성직|신성/.test(d)) return 'theology';
  return 'common';
}

function zoneOfLocation(location = '') {
  const text = String(location || '');
  const zones = new Set();
  if (/A동|1학년 기숙사|기숙사/.test(text)) zones.add('dormA');
  if (/기사|연무|대련|훈련장/.test(text)) zones.add('knight');
  if (/마법|마탑|실험|연구/.test(text)) zones.add('magic');
  if (/신학|성당|예배|신성/.test(text)) zones.add('theology');
  if (/도서|서고|열람|자료/.test(text)) zones.add('library');
  if (/학생회|회의실|귀빈/.test(text)) zones.add('council');
  if (/의료|치유|보건/.test(text)) zones.add('medical');
  if (/정원|호수|숲|중정/.test(text)) zones.add('garden');
  if (/상점|시장|길드|도시|아스테리온/.test(text)) zones.add('city');
  if (/식당|본관|복도|대강당|광장|교내|아카데미/.test(text)) zones.add('common');
  if (!zones.size) zones.add('common');
  return zones;
}

function overlapsArea(currentZones, area = '') {
  const z = zoneOfLocation(area);
  for (const item of z) if (currentZones.has(item)) return true;
  return false;
}

function recentSpeakerCounts(recentTurns = [], limit = 7) {
  const counts = {};
  for (const turn of recentTurns.slice(-limit)) {
    const seen = new Set();
    for (const item of turn?.scene || []) {
      if (item?.speaker_key && DIRECTOR_ROSTER[item.speaker_key]) seen.add(item.speaker_key);
    }
    for (const key of seen) counts[key] = (counts[key] || 0) + 1;
  }
  return counts;
}

function routineStreakOf(recentTurns = []) {
  let n = 0;
  for (let i = recentTurns.length - 1; i >= 0; i--) {
    if (recentTurns[i]?.importance === 'routine') n += 1;
    else break;
  }
  return n;
}

function activeHookNpcKeys(saveState = {}) {
  const out = new Set();
  for (const h of saveState?.hooks || []) {
    if (!h?.source_npc_key || ['resolved','expired'].includes(h?.status)) continue;
    out.add(h.source_npc_key);
  }
  return out;
}

function dueParticipantKeys(saveState = {}) {
  const out = new Set();
  for (const ev of saveState?.scheduleContext?.due || []) {
    for (const key of ev?.participants || []) out.add(key);
  }
  for (const ev of saveState?.scheduleContext?.upcoming || []) {
    const mins = ev?.date === saveState?.world?.date
      ? (() => {
          const [h1,m1] = String(ev?.time||'00:00').split(':').map(Number);
          const [h0,m0] = String(saveState?.world?.time||'00:00').split(':').map(Number);
          return (h1*60+m1)-(h0*60+m0);
        })()
      : 9999;
    if (mins >= 0 && mins <= 60) for (const key of ev?.participants || []) out.add(key);
  }
  return out;
}

function relationshipWeight(row = {}) {
  const affinity = Math.abs(Number(row?.affinity || 0));
  const trust = Math.abs(Number(row?.trust || 0));
  return Math.min(3.0, (affinity + trust) / 40);
}

function candidateScore(key, meta, ctx) {
  const {
    pcDept, zones, turnNumber, director, recentCounts, focused,
    hookKeys, scheduledKeys, npcSchedule, crossDue
  } = ctx;
  let score = 0;
  const reasons = [];

  if (focused.has(key)) { score += 20; reasons.push('사용자가 직접 지목/탐색'); }
  if (hookKeys.has(key)) { score += 7; reasons.push('미해결 훅'); }
  if (scheduledKeys.has(key)) { score += 8; reasons.push('현재/임박 일정 관련'); }

  const sched = npcSchedule?.[key];
  if (sched?.confidence === 'fixed' && !overlapsArea(zones, sched?.area || '')) {
    if (!focused.has(key) && !hookKeys.has(key) && !scheduledKeys.has(key)) return { score:-999, reasons:['고정 일정상 다른 장소'] };
  } else if (sched && overlapsArea(zones, sched?.area || '')) {
    score += sched.confidence === 'fixed' ? 6 : 2;
    reasons.push(`NPC 일정 ${sched.confidence}`);
  }

  let zoneHit = 0;
  for (const z of meta.zones || []) if (zones.has(z)) zoneHit += 1;
  if (zoneHit) {
    score += 3 + Math.min(3, zoneHit);
    reasons.push('현재 장소와 자연스러움');
  } else {
    const exclusive = [...zones].some(z => ['knight','magic','theology','medical','council'].includes(z));
    if (exclusive && !meta.zones.includes('common')) score -= 5;
    else score -= 1;
  }

  if (meta.dept === pcDept) score += 1.5;
  else if (['knight','magic','theology'].includes(meta.dept) && crossDue) {
    score += 3;
    reasons.push('타 학과 노출 공백');
  }

  if (meta.year === 1 && zones.has('dormA')) score += 4;
  if (meta.year > 1 && zones.has('dormA')) score -= 3;
  if (meta.roles.includes('faculty') && zones.has('dormA')) score -= 3;

  if (turnNumber < 8 && meta.year > 1 && !focused.has(key) && !hookKeys.has(key) && !scheduledKeys.has(key)) score -= 2.5;

  const exposure = director?.npcExposure?.[key] || {};
  const rawLastSeen = Number(exposure.lastSeenTurn);
  const lastSeen = Number.isFinite(rawLastSeen) ? rawLastSeen : -8;
  const gap = Math.max(0, turnNumber - lastSeen);
  if (gap >= 5) {
    score += Math.min(5, 1.2 + gap * 0.22);
    reasons.push(`최근 노출 공백 ${gap}턴`);
  }
  if (gap <= 1 && !focused.has(key)) score -= 6;
  else if (gap <= 3 && !focused.has(key)) score -= 2.5;

  const recentN = Number(recentCounts[key] || 0);
  if (recentN >= 3 && !focused.has(key)) {
    score -= 7 + (recentN - 3) * 2;
    reasons.push(`최근 과다 노출 ${recentN}회`);
  } else if (recentN === 2 && !focused.has(key)) score -= 3;

  score += relationshipWeight(ctx.relationships?.[key] || {});
  return { score, reasons };
}

function callbackRows(saveState = {}, turnNumber = 0) {
  return (saveState?.director?.callbacks || [])
    .filter(x => x && ['open','opportunity'].includes(x.status))
    .map(x => ({
      key:String(x.key||'').slice(0,80),
      status:x.status,
      age:Math.max(0, turnNumber - Number(x.createdTurn || turnNumber)),
      note:String(x.note||'').slice(0,220),
      spotlight_keys:Array.isArray(x.spotlight_keys) ? x.spotlight_keys.slice(0,4) : [],
    }))
    .filter(x=>x.key)
    .sort((a,b)=>b.age-a.age)
    .slice(0,8);
}

function buildDirectorContext({ saveState = {}, recentTurns = [], action = '', inputMode = 'game' } = {}) {
  const turnNumber = Number(saveState?.turnNumber || 0);
  const director = saveState?.director || {};
  const pcDept = deptOfPc(saveState?.pc || {});
  const location = String(saveState?.world?.location || '');
  const zones = zoneOfLocation(location);
  const focused = collectMentionedNpcKeys(action);
  const hookKeys = activeHookNpcKeys(saveState);
  const scheduledKeys = dueParticipantKeys(saveState);
  const recentCounts = recentSpeakerCounts(recentTurns);
  const npcSchedule = saveState?.scheduleContext?.npc_schedule || {};
  const routineStreak = routineStreakOf(recentTurns);

  const lastEventTurn = Number.isFinite(Number(director?.lastEventTurn)) ? Number(director.lastEventTurn) : 0;
  const lastChoiceTurn = Number.isFinite(Number(director?.lastChoicePressureTurn)) ? Number(director.lastChoicePressureTurn) : 0;
  const lastCrossTurn = Number.isFinite(Number(director?.lastCrossDepartmentTurn)) ? Number(director.lastCrossDepartmentTurn) : 0;
  const eventGap = Math.max(0, turnNumber - lastEventTurn);
  const choiceGap = Math.max(0, turnNumber - lastChoiceTurn);
  const crossGap = Math.max(0, turnNumber - lastCrossTurn);
  const crossDue = crossGap >= 6;
  const choiceDue = choiceGap >= 4;
  const callbacks = callbackRows(saveState, turnNumber);
  const payoffDue = callbacks.some(x => x.age >= 2);

  const dueCount = Array.isArray(saveState?.scheduleContext?.due) ? saveState.scheduleContext.due.length : 0;
  const lastImportance = recentTurns.at(-1)?.importance || null;

  let intervention = 'light';
  let objective = '현재 흐름을 유지하되, 설명보다 반응과 행동을 우선한다.';
  if (inputMode === 'meta') {
    intervention = 'none';
    objective = 'META FREEZE. 어떤 인게임 사건도 생성하거나 진행하지 않는다.';
  } else if (lastImportance === 'critical') {
    intervention = 'aftermath';
    objective = '큰 사건 직후의 결과/후유증을 짧게 보여주고 숨 돌릴 틈을 준다. 즉시 더 큰 사건을 겹치지 않는다.';
  } else if (dueCount > 0) {
    intervention = 'scheduled';
    objective = '이미 발생 중인 고정 일정을 우선한다. PC를 강제 참석시키지 말고, PC 위치에서 접할 수 있는 결과/접점을 만든다.';
  } else if (payoffDue) {
    intervention = 'medium';
    objective = '기존 마찰/고구마의 회수 기회가 숙성됐다. 개연성이 맞으면 PC가 직접 뒤집거나 증명할 수 있는 사이다 "기회"를 제시하되 결과는 대신 확정하지 않는다.';
  } else if (routineStreak >= 2 || eventGap >= 3) {
    intervention = 'medium';
    objective = '흐름이 평평하다. 현재 장소/시간/기존 NPC 목표에서 작은 사건이나 만남을 하나 만들어 장면을 움직인다.';
  }

  const ctx = {
    pcDept, zones, turnNumber, director, recentCounts, focused, hookKeys, scheduledKeys,
    npcSchedule, crossDue, relationships: saveState?.relationships || {}
  };

  const candidates = [];
  for (const [key, meta] of Object.entries(DIRECTOR_ROSTER)) {
    if (ROTATION_LOCKED.has(key)) continue;
    const row = candidateScore(key, meta, ctx);
    if (row.score <= -900) continue;
    candidates.push({
      key,
      name:CHARACTER_REGISTRY[key] || key,
      dept:meta.dept,
      score:Number(row.score.toFixed(2)),
      reasons:row.reasons.slice(0,4),
    });
  }
  candidates.sort((a,b)=>b.score-a.score);

  const crossCandidates = candidates
    .filter(x => ['knight','magic','theology'].includes(x.dept) && x.dept !== pcDept)
    .slice(0,4);

  let eventPreference = [];
  if (callbacks.length) eventPreference.push('기존 마찰/약속/훅의 회수 또는 후폭풍');
  if (crossDue && crossCandidates.length) eventPreference.push('현재 동선을 해치지 않는 타 학과/다른 인물과의 교차 접점');
  if (choiceDue) eventPreference.push('서로 비용이 다른 두 방향이 생기는 판단 지점');
  eventPreference.push('NPC 목표에서 시작되는 소형 조우/부탁/경쟁/오해/소문/사소한 사고');
  eventPreference.push('NPC-NPC 상호작용을 PC가 발견하거나 스쳐 지나가는 장면');
  eventPreference = eventPreference.slice(0,5);

  return {
    intervention,
    objective,
    routineStreak,
    eventGap,
    choiceGap,
    crossGap,
    choiceDue,
    crossDue,
    payoffDue,
    focusedKeys:[...focused].slice(0,6),
    candidates:candidates.slice(0,6),
    crossCandidates,
    callbacks,
    eventPreference,
  };
}

function directorContextText(ctx = {}) {
  const lines = [];
  lines.push(`INTERVENTION: ${ctx.intervention || 'light'}`);
  lines.push(`OBJECTIVE: ${ctx.objective || '-'}`);
  lines.push(`ROUTINE_STREAK=${ctx.routineStreak||0} / EVENT_GAP=${ctx.eventGap||0} / CHOICE_GAP=${ctx.choiceGap||0} / CROSS_DEPT_GAP=${ctx.crossGap||0}`);
  lines.push(`CHOICE_PRESSURE_DUE=${ctx.choiceDue?'YES':'NO'} / CROSS_DEPT_BRIDGE_DUE=${ctx.crossDue?'YES':'NO'} / PAYOFF_DUE=${ctx.payoffDue?'YES':'NO'}`);
  if (ctx.focusedKeys?.length) lines.push(`USER_FOCUS: ${ctx.focusedKeys.join(', ')}`);
  if (ctx.candidates?.length) {
    lines.push('SPOTLIGHT CANDIDATES (등장 강제가 아니라 개연성 있는 우선 후보):');
    for (const x of ctx.candidates) lines.push(`- ${x.key}(${x.name}) score=${x.score}: ${x.reasons.join(' / ') || '일반 후보'}`);
  }
  if (ctx.crossCandidates?.length) lines.push(`CROSS-DEPARTMENT BRIDGE: ${ctx.crossCandidates.map(x=>`${x.key}(${x.name})`).join(', ')}`);
  if (ctx.callbacks?.length) {
    lines.push('OPEN FRICTION/PAYOFF CALLBACKS:');
    for (const x of ctx.callbacks) lines.push(`- ${x.key} [${x.status}] age=${x.age}: ${x.note || '-'}`);
  }
  if (ctx.eventPreference?.length) {
    lines.push('PREFERRED EVENT SOURCES:');
    for (const x of ctx.eventPreference) lines.push(`- ${x}`);
  }
  lines.push('DIRECTOR GUARDRAILS:');
  lines.push('- 후보 점수 때문에 NPC를 순간이동시키지 않는다. 현재 위치/일정/목표의 개연성이 항상 우선이다.');
  lines.push('- 최근 자주 나온 NPC는 사용자가 직접 찾거나 현재 사건이 요구하지 않는 한 잠깐 쉬게 한다.');
  lines.push('- 안 나온 캐릭터를 균등 배분하는 것이 아니라 "자연스럽게 만날 기회"만 늘린다.');
  lines.push('- 사도/마신/천상사강/극비 인물은 스포트라이트 부채 때문에 절대 랜덤 등장시키지 않는다.');
  lines.push('- GM은 고구마를 만들 수 있지만 PC 대신 사이다를 실행하지 않는다. 해결/반격/증명의 기회만 판에 올린다.');
  lines.push('- 소형 이벤트가 끝나면 FACT/OBSERVER/BELIEF/RUMOR/HOOK/관계 후속으로 세계에 흔적을 남긴다.');
  return lines.join('\n');
}
// ===== END event-director.js =====

// ===== BEGIN memory.js =====
const trimText = (value, max = 400) => {
  const text = String(value ?? '');
  return text.length > max ? `${text.slice(0, max)}…` : text;
};

const memoryPriority = (value) => {
  if (typeof value === 'number') return Math.max(1, Math.min(5, value));
  return ({minor:2,routine:2,major:4,important:4,critical:5}[String(value||'').toLowerCase()] || 2);
};
const cleanMemory = (memory) => ({
  type: memory?.type || (Number(memory?.secret_level||0) >= 3 ? 'secret' : 'fact'),
  fact: trimText(memory?.fact, 420),
  importance: memoryPriority(memory?.importance),
  secret_level: Number(memory?.secret_level || 0),
  turn: Number(memory?.turn || 0),
  subject: trimText(memory?.subject || '', 120) || null,
  source: trimText(memory?.source || '', 180) || null,
  confidence: memory?.confidence == null ? null : Math.max(0, Math.min(1, Number(memory.confidence) || 0)),
  status: trimText(memory?.status || '', 40) || null,
});

const scoreRelationship = (row = {}) => Math.abs(Number(row.affinity || 0)) + Math.abs(Number(row.trust || 0));

function recentSpeakerKeys(recentTurns = []) {
  const keys = new Set();
  for (const turn of recentTurns.slice(-6)) {
    for (const item of turn?.scene || []) if (item?.speaker_key) keys.add(item.speaker_key);
  }
  return keys;
}

function relevantKeys(saveState, action, recentTurns) {
  const keys = collectMentionedNpcKeys(action, JSON.stringify(recentTurns || []));
  for (const key of recentSpeakerKeys(recentTurns)) keys.add(key);

  const location = saveState?.world?.location;
  for (const [key, state] of Object.entries(saveState?.npcStates || {})) {
    if (location && state?.location === location) keys.add(key);
  }

  for (const hook of saveState?.hooks || []) {
    if (hook?.source_npc_key && !['resolved','expired'].includes(hook?.status)) keys.add(hook.source_npc_key);
  }

  const topRelationships = Object.entries(saveState?.relationships || {})
    .filter(([, row]) => scoreRelationship(row) > 0 || row?.status && row.status !== '중립')
    .sort((a, b) => scoreRelationship(b[1]) - scoreRelationship(a[1]))
    .slice(0, 8)
    .map(([key]) => key);
  for (const key of topRelationships) keys.add(key);
  return keys;
}

function compactRelationships(relationships = {}, relevant = new Set()) {
  const selected = Object.entries(relationships)
    .filter(([key, row]) => relevant.has(key) || scoreRelationship(row) > 0 || (row?.status && row.status !== '중립'))
    .sort((a,b) => (relevant.has(b[0]) ? 1 : 0) - (relevant.has(a[0]) ? 1 : 0) || scoreRelationship(b[1]) - scoreRelationship(a[1]))
    .slice(0, 16);
  return Object.fromEntries(selected.map(([key, row]) => [key, {
    affinity: Number(row?.affinity || 0),
    trust: Number(row?.trust || 0),
    status: row?.status || '중립',
    history: (row?.history || []).slice(relevant.has(key) ? -8 : -2).map((x) => trimText(x, 200)),
  }]));
}

function compactIntimacyStates(states = {}, relevant = new Set()) {
  const selected = Object.entries(states || {})
    .filter(([key, row]) => relevant.has(key) || Number(row?.level || 0) > 0)
    .sort((a,b) => Number(b[1]?.level || 0) - Number(a[1]?.level || 0))
    .slice(0, 12);
  return Object.fromEntries(selected.map(([key, row]) => [key, {
    level: Math.max(0, Math.min(5, Number(row?.level || 0))),
    status: trimText(row?.status || '없음', 80),
    history: (row?.history || []).slice(relevant.has(key) ? -6 : -2).map((x) => trimText(x, 180)),
  }]));
}

function compactNpcMemories(memories = {}, relevant = new Set()) {
  const selected = {};
  const criticalFromOthers = [];
  for (const [key, rows] of Object.entries(memories || {})) {
    const cleanRows = (rows || []).map(cleanMemory).filter((x) => x.fact);
    if (relevant.has(key)) selected[key] = cleanRows.slice(-18);
    else for (const row of cleanRows) if (row.importance >= 4) criticalFromOthers.push({ npc_key: key, ...row });
  }
  return { relevant: selected, critical_elsewhere: criticalFromOthers.slice(-24) };
}

function compactEmotionStates(states = {}, relevant = new Set()) {
  const out = {};
  for (const [key, row] of Object.entries(states || {})) {
    if (!relevant.has(key) && Number(row?.lastSeenTurn ?? -99) < 0) continue;
    if (!relevant.has(key) && Object.keys(out).length >= 8) continue;
    out[key] = {
      current: row?.current || 'default',
      intensity: Number(row?.intensity || 0),
      turnsHeld: Number(row?.turnsHeld || 0),
      lastChangedTurn: Number(row?.lastChangedTurn ?? -1),
      reason: trimText(row?.reason || '', 160),
    };
  }
  return out;
}

function compactSaveForModel(saveState = {}, { action = '', recentTurns = [] } = {}) {
  const relevant = relevantKeys(saveState, action, recentTurns);
  const globalMemory = (saveState?.memories?.global || []).map(cleanMemory).filter((x) => x.fact);
  const majorGlobal = globalMemory.filter((x) => x.importance >= 3).slice(-40);
  const recentMinorGlobal = globalMemory.filter((x) => x.importance < 3).slice(-10);

  const npcStates = Object.fromEntries(Object.entries(saveState?.npcStates || {})
    .filter(([key, row]) => relevant.has(key) || row?.location === saveState?.world?.location)
    .slice(0, 18)
    .map(([key, row]) => [key, {
      location: trimText(row?.location, 120),
      status: trimText(row?.status, 160),
      current_goal: trimText(row?.current_goal, 200),
      last_seen: trimText(row?.last_seen, 120),
    }]));

  return {
    version: saveState?.version || 3,
    turnNumber: Number(saveState?.turnNumber || 0),
    world: saveState?.world || {},
    pc: saveState?.pc || {},
    relationships: compactRelationships(saveState?.relationships || {}, relevant),
    intimacyStates: compactIntimacyStates(saveState?.intimacyStates || {}, relevant),
    npcStates,
    emotionStates: compactEmotionStates(saveState?.emotionStates || {}, relevant),
    activeEvents: (saveState?.activeEvents || []).slice(-40),
    completedEvents: (saveState?.completedEvents || []).slice(-40),
    pcKnowledge: (saveState?.pcKnowledge || []).slice(-80).map((x) => trimText(x, 380)),
    memories: {
      global: [...majorGlobal, ...recentMinorGlobal].slice(-48),
      npc: compactNpcMemories(saveState?.memories?.npc || {}, relevant),
    },
    relevantNpcKeys: [...relevant].slice(0, 18),
    scheduledEvents: (saveState?.scheduledEvents || []).filter(x => x?.status !== 'completed' && x?.status !== 'cancelled').slice(0,24),
    hooks: (saveState?.hooks || []).filter(x => !['resolved','expired'].includes(x?.status)).slice(-30),
    scheduleContext: saveState?.scheduleContext || {},
    director: {
      lastEventTurn: Number(saveState?.director?.lastEventTurn || 0),
      lastChoicePressureTurn: Number(saveState?.director?.lastChoicePressureTurn || 0),
      lastCrossDepartmentTurn: Number(saveState?.director?.lastCrossDepartmentTurn || 0),
      recentBeats: (saveState?.director?.recentBeats || []).slice(-10),
      callbacks: (saveState?.director?.callbacks || []).filter(x=>x?.status!=='resolved').slice(-10),
    },
    flags: saveState?.flags || {},
  };
}
// ===== END memory.js =====

// ===== BEGIN prompt.js =====
const cut = (value, max = 9000) => {
  const text = typeof value === 'string' ? value : JSON.stringify(value ?? null);
  return text.length > max ? `${text.slice(0, max)}\n...[잘림]` : text;
};

const compactRecentTurns = (recentTurns = []) => recentTurns.slice(-6).map((turn) => ({
  action: cut(turn?.action || '', 700),
  summary: cut(turn?.summary || '', 900),
  importance: turn?.importance || null,
  scene: (turn?.scene || []).slice(-6).map((item) => ({
    kind: item?.kind,
    text: cut(item?.text || '', 360),
    speaker_key: item?.speaker_key || null,
    expression: item?.display_expression || item?.expression || null,
  })),
}));

// 절대 변하지 않는 prefix. prompt caching의 효율을 위해 설정 토글을 여기에 섞지 않는다.
function buildInstructions() {
  return `${GM_RULES}\n\n===== GM STYLE CANON V4 =====\n${GM_STYLE_V4}\n\n===== CHARACTER REGISTRY =====\n${CHARACTER_REGISTRY_TEXT}\n\n===== WORLD CANON =====\n${CANON.world}\n\n===== NPC CANON =====\n${CANON.npc}\n\n===== NPC SPEECH =====\n${CANON.speech}\n\n===== OPTIONAL ADULT / INTIMACY SPEECH LAYER =====\n${CANON.adult}\n이 레이어는 TURN OPTIONS의 ADULT_MODE가 ON이고, PC와 해당 장면 참여자가 모두 성인이며 자유로운 상호 동의와 관계 맥락이 충족될 때만 활성화한다. OFF이면 친밀/성인 수위 규칙을 사용하지 않는다. ON이면 관계단계에 맞춰 성인다운 직접적 플러팅, 욕망 표현, 깊은 키스, 포옹, 밀착, 목/어깨 입맞춤, 비그래픽 손길, 호흡·체온·떨림·옷매무새, 침실/개인실 장면전환과 관계 후 대화를 충분히 활용한다. 구체적인 성행위 단계별 동작, 성기, 삽입, 구강행위 세부, 체액은 묘사하지 않는다.\n\n===== PC SYSTEM =====\n${CANON.pc_system}\n\n===== INITIAL CURRENT STATE =====\n${CANON.current}`;
}

function buildTurnInput({ action, saveState, recentTurns, rollingSummary, availableCgIds = [], adultMode = false, adultEligible = false, proseLength = 'medium', inputMode = 'game' }) {
  const compactSave = compactSaveForModel(saveState, { action, recentTurns });
  const turns = compactRecentTurns(recentTurns);
  const directorContext = buildDirectorContext({ saveState, recentTurns, action, inputMode });
  const directorText = directorContextText(directorContext);
  const cgIds = Array.isArray(availableCgIds) ? availableCgIds.slice(0, 100) : [];
  let routineStreak = 0;
  for (let i = recentTurns.length - 1; i >= 0; i--) {
    if (recentTurns[i]?.importance === 'routine') routineStreak += 1;
    else break;
  }
  const pacingPressure = directorContext.intervention === 'medium'
    ? 'HIGH — EVENT DIRECTOR가 개입을 권고한다. 기존 맥락에서 작은 사건/조우/마찰/회수 기회 중 하나로 흐름을 움직여라.'
    : directorContext.intervention === 'scheduled'
      ? 'SCHEDULED — 세계 일정이 우선이다. PC 강제 이동 없이 일정의 진행과 접점을 반영하라.'
      : directorContext.intervention === 'aftermath'
        ? 'AFTERMATH — 큰 사건 직후다. 결과와 후유증을 짧게 보여주고 즉시 더 큰 사건을 겹치지 마라.'
        : routineStreak === 1
          ? 'MEDIUM — 일상은 짧게 마무리하고 다음 의미 있는 접점을 가까이 배치하라.'
          : 'NORMAL — 현재 사건의 호흡을 유지하되 설명 때문에 정체시키지 마라.';
  const lengthRule = proseLength === 'short'
    ? '매우 빠르게. ROUTINE은 즉시 압축하고 핵심 반응/사건만.'
    : proseLength === 'long'
      ? '중요 장면은 충분히 묘사하되 ROUTINE은 여전히 짧게 압축하고 반복 금지.'
      : '자동형. ROUTINE은 짧게, 대화·갈등·전투·중요 사건만 필요한 만큼 확대.';
  return `===== TURN OPTIONS =====\nINPUT_MODE: ${inputMode === 'meta' ? 'META' : 'GAME'}\n서술 길이: ${lengthRule}\nROUTINE_STREAK: ${routineStreak}\nPACING_PRESSURE: ${pacingPressure}\nADULT_MODE: ${adultMode && adultEligible ? 'ON' : 'OFF'}\n성인 조건 충족: ${adultEligible ? 'YES' : 'NO'}\n\n===== AUTHORITATIVE SAVE_STATE =====\n${cut(compactSave, 42000)}\n\n===== ROLLING SUMMARY =====\n${cut(rollingSummary || '아직 없음', 6500)}\n\n===== RECENT TURNS =====\n${cut(turns, 12000)}\n\n===== AVAILABLE_CG_IDS =====\n${cgIds.length ? cgIds.join(', ') : '없음'}\n\n===== GM EVENT DIRECTOR (SERVER GUIDANCE) =====\n${cut(directorText, 9000)}\n\n===== SCHEDULE ENGINE (AUTHORITATIVE) =====
${cut(saveState?.scheduleContext || {}, 6500)}

===== USER ACTION =====\n${cut(action, 5000)}\n\n위 행동까지만 처리하고 PC의 다음 행동은 정하지 마라.
ROUTINE 장면은 빠르게: 보통 narration 1~2개 + 필요한 짧은 대사 정도로 끝내라. 방/복도/시설/출석/안내를 길게 풀지 마라.
NPC의 대사는 설명문이 아니라 실제 반응·질문·농담·도발·결정이 되게 하라. 사실 설명은 narration으로 짧게 옮겨라.
AUTHORITATIVE SAVE_STATE에 이미 있는 이름/출신/학과 등을 단순 행정 확인 때문에 사용자에게 다시 묻지 마라.
최근 ROUTINE_STREAK와 GM EVENT DIRECTOR를 함께 따른다. Director 후보는 등장 명령이 아니라 '자연스러운 후보'다. 위치/일정/사용자의 직접 선택이 항상 우선이다. 작은 이벤트를 자주 쓰되 대형 사건을 남발하지 말고, 몇 턴마다 한 번은 서로 다른 비용/정보를 가진 고민거리를 만들어라.
고구마/마찰을 만든 턴에는 나중에 회수할 가치가 있으면 director.callback_key/phase를 남겨라. 사이다는 자동 승리가 아니라 PC가 직접 증명·반격·협상·우회할 PAYOFF_OPPORTUNITY로 제공하라.
각 주요 NPC 대사에는 실제 감정 태그/강도/근거를 함께 반환하라. 미래 약속이 명확히 성립하면 scheduled_events_add를 사용하고, 장기 기억은 type과 importance 1~5를 정확히 분류하라.
INPUT_MODE가 META라면 인게임 장면을 이어가지 말고 요청한 설정/기억/규칙/디버그 질문에만 답한다. META에서는 모든 state_delta 배열을 비우고 advance_minutes=0으로 반환하라.`;
}
