// ===== BEGIN router.js =====
const IMPORTANT_RE = /(전투|공격|기습|결투|살해|죽음|도망|추적|구출|협상|정치|황위|비밀|조사|잠입|권능|사도|대죄주교|마신|심연|Delphirem|부상|치료|판정|대련|시험|고백|배신|의식|L4|L5)/i;
const REASONING_LEVELS = new Set(['none', 'low', 'medium', 'high', 'xhigh', 'max']);

function actionPhraseAt(action, index) {
  const text = String(action || '');
  const separator = /(?:지\s*않고|지\s*못하고|지\s*말고|모르고|지만|그리고|그러나|하지만|그렇지만)\s*|\band\s+then\b[\s,]*|\bbut\b[\s,]*|[\n.!?;。！？]+/gi;
  let start = 0;
  let end = text.length;
  for (const match of text.matchAll(separator)) {
    const separatorStart = match.index || 0;
    const separatorEnd = separatorStart + match[0].length;
    if (separatorEnd <= index) {
      start = separatorEnd;
      continue;
    }
    end = separatorEnd;
    break;
  }
  return text.slice(start, end).trim();
}

function isNonCommittedPhrase(phrase) {
  const text = String(phrase || '').trim();
  if (!text) return true;
  if (/[?？]/.test(text)) return true;
  if (/(?:(?:언제|누구|누가|무엇|뭐|어디|왜|어떻게|어느|몇).*(?:야|니|냐|나요|까|지)|(?:알려|설명해|말해|가르쳐)\s*(?:줘|주세요|줄래)|궁금(?:해|하다)|정보(?:를|가)?\s*[.!。！]?$)/.test(text)) return true;
  if (/(?:만약|가정(?:하면|해서|하자면)?|상상(?:하면|해서)?|경우(?:에는|엔)?|(?:으|라|다|한다|된다|온다|오|하|되|이|라)면\b|면[,.\s]|면$|고\s*싶|(?:할|될|일)\s*수\s*있|(?:하|되|이)려면|(?:한|할|된|될)\s*때|해도)/.test(text)) return true;
  if (/\b(?:if|unless|suppose|assuming|imagine|hypothetically|maybe|would|could|should|can|may|want|wish|what|who|when|where|why|how|explain|information)\b/i.test(text)) return true;
  if (/(?:하지|되지|아니|않|못하|못해|못했|못할|말자|말고|말아|말라)|(?:^|\s)안\s/.test(text)) return true;
  if (/(?:모(?:르|른|를|릅)|아는\s*(?:것|게|바)?\s*(?:이\s*)?없)/.test(text)) return true;
  if (/\b(?:do\s+not|don't|not|never|won't|will\s+not)\b/i.test(text)) return true;
  if (/\b(?:have\s+no\s+idea|know\s+nothing|(?:am|are|is)\s+not\s+sure)\b/i.test(text)) return true;
  if (/(?:알려|설명해|말해|가르쳐)\s*[.!。！]?$/.test(text)) return true;
  if (/(?:는|은|냐|니|나요|인가요|일까요|[가-힣]+까(?:요)?|해도\s*돼|해도\s*될까)\s*[.!。！]?$/.test(text)) return true;
  return false;
}

function hasCommittedFindFollowup(action, index) {
  const tail = String(action || '').slice(index);
  const followup = tail.match(/(?:지만|그리고|그러나|하지만|그렇지만)\s*([^.!?。！？]+[.!?。！？]?)|\b(?:but|and\s+then)\b[\s,]*([^.!?]+[.!?]?)/i);
  const phrase = (followup?.[1] || followup?.[2] || '').trim();
  return /(?:찾으러|찾는다|찾아가|수색|추적|go\s+(?:and\s+)?find|find\s+them|seek|look\s+for)/i.test(phrase) && !isNonCommittedPhrase(phrase);
}

function hasAffirmedActionKeyword(action, pattern) {
  const matcher = new RegExp(pattern.source, pattern.flags.includes('g') ? pattern.flags : `${pattern.flags}g`);
  for (const match of String(action).matchAll(matcher)) {
    if (!isNonCommittedPhrase(actionPhraseAt(action, match.index || 0)) || (/^(?:L4|L5|델피렘|Delphirem|마신|대죄주교|사도|어비스|심연)$/i.test(match[0]) && hasCommittedFindFollowup(action, match.index || 0))) return true;
  }
  return false;
}

function chooseModel({ mode = 'auto', action = '', saveState = {}, proReasoning = false, forceTerra = false }) {
  const luna = process.env.OPENAI_MODEL_LUNA || 'gpt-5.6-luna';
  const terra = process.env.OPENAI_MODEL_TERRA || 'gpt-5.6-terra';

  if (proReasoning) return { model: terra, tier: 'terra', reason: 'pro-mode' };
  if (forceTerra) return { model: terra, tier: 'terra', reason: 'one-turn-force' };
  if (mode === 'luna') return { model: luna, tier: 'luna', reason: 'manual-luna' };
  if (mode === 'terra') return { model: terra, tier: 'terra', reason: 'manual-terra' };

  const forced = Boolean(saveState?.flags?.forceTerraNextTurn);
  const major = Boolean(saveState?.flags?.majorScene);
  const importantAction = hasAffirmedActionKeyword(action, IMPORTANT_RE);
  const dueSchedule = (saveState?.scheduleContext?.due || []).some(ev => Number(ev?.importance || 0) >= 4);
  if (forced) return { model: terra, tier: 'terra', reason: 'save-flag' };
  if (major) return { model: terra, tier: 'terra', reason: 'critical-followup' };
  if (dueSchedule) return { model: terra, tier: 'terra', reason: 'scheduled-major-event' };
  if (importantAction) return { model: terra, tier: 'terra', reason: 'important-keyword' };
  return { model: luna, tier: 'luna', reason: 'routine' };
}

function reasoningFor(tier, requested = 'auto', proReasoning = false) {
  if (requested && requested !== 'auto' && REASONING_LEVELS.has(requested)) {
    if (proReasoning && requested === 'none') return 'medium';
    return requested;
  }
  if (proReasoning) return 'high';
  return tier === 'terra' ? 'medium' : 'low';
}
